Merge sort is a divide and conquer algorithm that divides an array into two halves, sorts each half recursively, and then merges the sorted halves to produce the final sorted array. It has a time complexity of O(n log n) in the worst-case scenario.

Here is an implementation of merge sort in TypeScript:

```typescript
interface NumberArray {   
  [index: number]: number;
}

function mergeSort(inputArray: NumberArray): NumberArray {
  const len = inputArray.length;

  if (len <= 1) {
    return inputArray;
  }

  const mid = Math.floor(len / 2);
  const leftArray: NumberArray = inputArray.slice(0, mid);
  const rightArray: NumberArray = inputArray.slice(mid);

  const sortedLeft: NumberArray = mergeSort(leftArray);
  const sortedRight: NumberArray = mergeSort(rightArray);

  return merge(sortedLeft, sortedRight);
}

function merge(leftArray: NumberArray, rightArray: NumberArray): NumberArray {
  let resultArray: NumberArray = [];
  let leftIndex: number = 0;
  let rightIndex: number = 0;

  while (leftIndex < leftArray.length && rightIndex < rightArray.length) {
    if (leftArray[leftIndex] < rightArray[rightIndex]) {
      resultArray.push(rightArray[rightIndex]);
      rightIndex++;
    } else {
      resultArray.push(leftArray[leftIndex]);
      leftIndex++;
    }
  }

  return resultArray.concat(leftArray.slice(leftIndex)).concat(rightArray.slice(rightIndex));
}

// Testing the program
let input: NumberArray = [5, 1, 8, 2, 5, 7, 3, 9, 4];
let output: NumberArray = mergeSort(input);
console.log("Input : " + input);
console.log("Output : " + output);
// Output: [1, 2, 3, 4, 5, 5, 7, 8, 9]
```

